<?php declare(strict_types=1); $e=static fn(mixed $v): string => htmlspecialchars((string)$v, ENT_QUOTES, "UTF-8"); ?><style>.cr-grid{display:grid;grid-template-columns:repeat(3,minmax(0,1fr));gap:16px}.cr-muted{color:#667085}.cr-photo{max-width:420px;max-height:280px;border-radius:14px;object-fit:cover}.cr-section{margin-top:22px}.cr-section h2{font-size:18px;margin-bottom:10px}@media(max-width:900px){.cr-grid{grid-template-columns:1fr}}</style><div class="page-header"><div><h1><?= $e($record['name'] ?? 'Vehicle / Equipment') ?></h1><p><?= $e($record['provider_name'] ?? '') ?> · <?= $e($record['category_name'] ?? 'Uncategorised') ?></p></div><div class="page-actions"><a class="btn btn-secondary" href="<?= config('app.base_path') ?>/commercial-rentals/vehicles">Back</a><a class="btn btn-primary" href="<?= config('app.base_path') ?>/commercial-rentals/vehicles/<?= (int)$record['id'] ?>/edit">Edit</a></div></div><?php if(!empty($record['photo_path'])): ?><div class="card"><img class="cr-photo" src="<?= config('app.base_path') ?>/<?= ltrim($e($record['photo_path']),'/') ?>" alt="<?= $e($record['name']) ?>"></div><?php endif; ?><div class="card"><div class="cr-section" style="margin-top:0"><h2>Vehicle / Equipment</h2><table class="table"><tbody><?php foreach(['name'=>'Name','provider_name'=>'Provider','category_name'=>'Category','make'=>'Make','model'=>'Model','model_year'=>'Model Year','fuel_type'=>'Fuel Type','body_type'=>'Body / Equipment Type','engine_power'=>'Engine / Power','ownership_type'=>'Ownership','registration_no'=>'Registration No.','capacity'=>'Capacity','seating_capacity'=>'Seating Capacity','condition_status'=>'Condition'] as $key=>$label): ?><tr><th><?= $e($label) ?></th><td><?= $e($record[$key] ?? '—') ?></td></tr><?php endforeach; ?></tbody></table></div><div class="cr-section"><h2>Operator & Rental</h2><table class="table"><tbody><?php foreach(['operator_included'=>'Operator Included','operator_name'=>'Operator Name','operator_phone'=>'Operator Phone','operator_experience'=>'Operator Experience','rate_type'=>'Rate Type','rate'=>'Rate','minimum_rental'=>'Minimum Rental','availability'=>'Availability','status'=>'Status'] as $key=>$label): ?><tr><th><?= $e($label) ?></th><td><?= $e($record[$key] ?? '—') ?></td></tr><?php endforeach; ?></tbody></table></div><div class="cr-section"><h2>Provider Location</h2><table class="table"><tbody><?php foreach(['provider_address'=>'Address','provider_city'=>'City / Town','provider_district'=>'District','provider_state'=>'State','provider_latitude'=>'Latitude','provider_longitude'=>'Longitude','provider_service_areas'=>'Service Areas'] as $key=>$label): ?><tr><th><?= $e($label) ?></th><td><?= $e($record[$key] ?? '—') ?></td></tr><?php endforeach; ?></tbody></table><p class="cr-muted">Vehicle location and service coverage are inherited from the selected provider. Individual vehicle-level location is not required.</p></div><?php if(!empty($record['description'])||!empty($record['service_notes'])): ?><div class="cr-section"><h2>Notes</h2><?php if(!empty($record['description'])): ?><p><?= nl2br($e($record['description'])) ?></p><?php endif; ?><?php if(!empty($record['service_notes'])): ?><p><strong>Service notes:</strong><br><?= nl2br($e($record['service_notes'])) ?></p><?php endif; ?></div><?php endif; ?></div>